<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import Icon from './components/Icon.vue'
import AccountAvatar from './components/AccountAvatar.vue'
import PaneView from './components/PaneView.vue'
import { api, applySnapshot, busy, connected, data, initialize, notice, pages, ready, run, toast, workspace } from './store'
import { moveTab, newTab, repairWorkspace, uid, visibleCount, closeWorkspaceTab, restoreWorkspaceTab, resizeSidebar, toggleSidebar } from '../shared/workspace'
import { layoutIds, type DeviceCode, type LayoutId, type PageId, type Pane, type Tab } from '../shared/model'
import { appearanceVariables } from '../shared/appearance'

const navigation:PageId[]=['instances','resources','tasks']
const utilities:PageId[]=['plugins','tools','settings']
const allPages:PageId[]=[...navigation,...utilities]
const navStyle=ref<'top'|'side'>((localStorage.getItem('half.navStyle') as 'top'|'side')||'top')
watch(navStyle,value=>{try{localStorage.setItem('half.navStyle',value)}catch{}})
const navCompact=ref(false)
const presetCompact=ref(false)
function measureNav(){navCompact.value=window.innerWidth<1180;presetCompact.value=window.innerWidth<1440}
const layoutNames:Record<LayoutId,string>={single:'单栏',columns:'左右双栏',rows:'上下双栏','left-wide':'左单右双','right-wide':'左双右单',quad:'四栏工作区'}
const activePane=computed(()=>workspace.value.panes.find(p=>p.id===workspace.value.focused)||workspace.value.panes[0])
const activePage=computed(()=>activePane.value.tabs.find(t=>t.id===activePane.value.active)?.page||'instances')
const maximizedPane=ref<string|null>(null)
const displayLayout=computed(()=>maximizedPane.value?'single':workspace.value.layout)
const visiblePanes=computed(()=>maximizedPane.value?workspace.value.panes.filter(p=>p.id===maximizedPane.value):workspace.value.panes.slice(0,visibleCount(workspace.value.layout)))
// 双栏（左右双栏 / 左单右双 / 左双右单）按相反顺序排布：编号大的在左，小的在右。
const displayPanes=computed(()=>{
  const layout=displayLayout.value
  const panes=visiblePanes.value
  return layout==='columns'||layout==='left-wide'||layout==='right-wide'?[...panes].reverse():panes
})
const activeTasks=computed(()=>data.tasks.filter(t=>t.status==='running').length)
const account=computed(()=>data.state.accounts.find(a=>a.id===data.state.selectedAccount))
const otherAccounts=computed(()=>data.state.accounts.filter(a=>a.id!==data.state.selectedAccount))
const workspaceElement=ref<HTMLElement>()
const presetOpen=ref(false),savePresetOpen=ref(false),presetName=ref(''),commandOpen=ref(false),commandQuery=ref(''),accountOpen=ref(false),accountMenuOpen=ref(false),sideAccountHover=ref(false),deviceCode=ref<DeviceCode|null>(null),loginPending=ref(false),maximized=ref(false)
const offlineName=ref(''),accountAddType=ref<'microsoft'|'offline'>('microsoft'),loginMethod=ref<'browser'|'device'|'inapp'>('browser'),loginStage=ref(''),loginCancelled=ref(false)
async function addOffline(){const ok=await run('offline-add','account.offline',offlineName.value);if(ok){offlineName.value='';toast('离线账户已添加')}}
const dragging=ref(''),resizing=ref(false)
const sidebarDragging=ref(false)
const sidebarStyle=computed(()=>({width:(workspace.value.sidebarCollapsed?56:workspace.value.sidebarWidth)+'px',minWidth:(workspace.value.sidebarCollapsed?56:workspace.value.sidebarWidth)+'px'}))
const tabContext=ref<{paneId:string;tabId:string;x:number;y:number}|null>(null)
const contextPane=computed(()=>workspace.value.panes.find(p=>p.id===tabContext.value?.paneId))
const contextTab=computed(()=>contextPane.value?.tabs.find(t=>t.id===tabContext.value?.tabId))
function showTabMenu(event:MouseEvent,pane:Pane,tab:Tab){tabContext.value={paneId:pane.id,tabId:tab.id,x:Math.max(8,Math.min(event.clientX,window.innerWidth-245)),y:Math.max(8,Math.min(event.clientY,window.innerHeight-370))}}
function sidebarResize(event:PointerEvent){event.preventDefault();sidebarDragging.value=true;(event.target as HTMLElement).setPointerCapture?.(event.pointerId);const left=(event.currentTarget as HTMLElement).parentElement!.getBoundingClientRect().left;const update=(e:PointerEvent)=>resizeSidebar(workspace.value,e.clientX-left);const end=()=>{sidebarDragging.value=false;window.removeEventListener('pointermove',update);window.removeEventListener('pointerup',end)};window.addEventListener('pointermove',update);window.addEventListener('pointerup',end,{once:true})}
function focusPane(pane:Pane){maximizedPane.value=maximizedPane.value===pane.id?null:pane.id;focus(pane)}
function navigationClick(event:MouseEvent,page:PageId){if(event.ctrlKey||event.metaKey)addTab(activePane.value,page);else navigate(page)}
function closeRelated(side:'others'|'right'){const pane=contextPane.value,tab=contextTab.value;if(!pane||!tab)return;const index=pane.tabs.indexOf(tab);const ids=pane.tabs.filter((t,i)=>t.id!==tab.id&&!t.pinned&&(side==='others'||i>index)).map(t=>t.id);for(const id of ids)closeWorkspaceTab(workspace.value,pane.id,id);tabContext.value=null}
function contextMove(toId:string){if(tabContext.value)moveTab(workspace.value,tabContext.value.paneId,toId,tabContext.value.tabId);tabContext.value=null}
const commandIndex=ref(0)
watch(commandQuery,()=>commandIndex.value=0)
watch(commandOpen,async open=>{if(open){commandIndex.value=0;await nextTick();document.querySelector<HTMLInputElement>('.command-search input')?.focus()}})
const plain=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
let saveTimer:ReturnType<typeof setTimeout>|undefined,stopEvents:(()=>void)|undefined
let pendingSave:Promise<any>=Promise.resolve()
function persist(){if(!ready.value||!connected.value)return Promise.resolve();pendingSave=api('workspace.save',plain(workspace.value)).catch(e=>{toast('工作区保存失败：'+e.message);throw e});return pendingSave}
watch(workspace,()=>{clearTimeout(saveTimer);saveTimer=setTimeout(()=>{void persist().catch(()=>{})},160)},{deep:true})
watch(()=>data.state.settings,s=>{document.documentElement.dataset.theme=s.theme;document.documentElement.style.setProperty('--font-scale',String(s.fontScale/100));document.documentElement.style.setProperty('--surface-alpha',String(Math.pow((s.opacity??100)/100,2)));document.documentElement.classList.toggle('glass',s.glass!==false);document.documentElement.classList.toggle('reduce-motion',s.reduceMotion);for(const [key,value] of Object.entries(appearanceVariables(s)))document.documentElement.style.setProperty(key,value)},{deep:true,immediate:true})
function tabOf(pane:Pane){return pane.tabs.find(t=>t.id===pane.active)||pane.tabs[0]}
function focus(pane:Pane){workspace.value.focused=pane.id}
function addTab(pane=activePane.value,page:PageId='instances',activate=true){if(pane.tabs.length>=40){toast('每栏最多打开 40 个标签');return}const tab=newTab(page);pane.tabs.push(tab);if(activate){pane.active=tab.id;focus(pane)}}
function closeTab(pane:Pane,tab:Tab){closeWorkspaceTab(workspace.value,pane.id,tab.id)}
function duplicateTab(pane:Pane,tab:Tab){if(pane.tabs.length>=40){toast('每栏最多打开 40 个标签');return}const copy={...plain(tab),id:uid(),pinned:false};pane.tabs.splice(pane.tabs.indexOf(tab)+1,0,copy);pane.active=copy.id;focus(pane)}
function navigate(page:PageId,pane=activePane.value){const tab=tabOf(pane);if(tab.pinned&&tab.page!==page){addTab(pane,page);return}tab.page=page;tab.query='';tab.group='';tab.scroll=0;focus(pane);presetOpen.value=false}
function setLayout(layout:LayoutId){maximizedPane.value=null;workspace.value.layout=layout;repairWorkspace(workspace.value)}
function startDrag(event:DragEvent,pane:Pane,tab:Tab){event.dataTransfer?.setData('application/x-hakf-tab',JSON.stringify({pane:pane.id,tab:tab.id}));if(event.dataTransfer)event.dataTransfer.effectAllowed='move';dragging.value=pane.id}
function drop(event:DragEvent,pane:Pane,before?:Tab){dragging.value='';try{const value=JSON.parse(event.dataTransfer?.getData('application/x-hakf-tab')||'null');if(value&&typeof value.pane==='string'&&typeof value.tab==='string')moveTab(workspace.value,value.pane,pane.id,value.tab,before?.id)}catch{toast('无法移动此标签')}}
const workspaceStyle=computed(()=>{const [x,y,z]=workspace.value.ratios;const l=displayLayout.value;return {gridTemplateColumns:l==='rows'||l==='single'?'minmax(0,1fr)':`minmax(0,${x}fr) minmax(0,${100-x}fr)`,gridTemplateRows:l==='columns'||l==='single'?'minmax(0,1fr)':`minmax(0,${l.endsWith('wide')?z:y}fr) minmax(0,${100-(l.endsWith('wide')?z:y)}fr)`}})
function resize(event:PointerEvent,index:number,axis:'x'|'y'){event.preventDefault();resizing.value=true;(event.target as HTMLElement).setPointerCapture?.(event.pointerId);const rect=workspaceElement.value!.getBoundingClientRect();const change=(e:PointerEvent)=>{workspace.value.ratios[index]=Math.round(Math.min(80,Math.max(20,((axis==='x'?e.clientX-rect.left:e.clientY-rect.top)/(axis==='x'?rect.width:rect.height))*100)))};const end=()=>{resizing.value=false;window.removeEventListener('pointermove',change);window.removeEventListener('pointerup',end)};window.addEventListener('pointermove',change);window.addEventListener('pointerup',end,{once:true})}
function adjustRatio(event:KeyboardEvent,index:number){if(['ArrowLeft','ArrowUp','ArrowRight','ArrowDown'].includes(event.key)){event.preventDefault();workspace.value.ratios[index]=Math.min(80,Math.max(20,workspace.value.ratios[index]+(['ArrowLeft','ArrowUp'].includes(event.key)?-2:2)))}}
async function savePreset(){const ok=await run('preset-save','preset.save',{name:presetName.value,workspace:plain(workspace.value)});if(ok){savePresetOpen.value=false;presetName.value='';toast('工作区预设已保存')}}
function openAccounts(){accountOpen.value=true}
async function login(){if(loginPending.value)return;loginCancelled.value=false;loginPending.value=true;loginStage.value='正在准备授权…';try{await api('account.login',loginMethod.value);toast('正版账户已添加');deviceCode.value=null}catch(e:any){if(!loginCancelled.value)toast(e.message+(loginMethod.value==='browser'?'。若浏览器跳转失败，请改用设备代码登录':''))}finally{loginPending.value=false;loginStage.value=''}}
async function cancelLogin(){loginCancelled.value=true;await run('login-cancel','account.cancel');deviceCode.value=null;toast('已取消登录')}
const commands=computed(()=>{
  const all=[...Object.entries(pages).filter(([id])=>id!=='install').map(([id,p])=>({id:'page-'+id,title:'打开'+p.title,description:p.sub,icon:id,action:()=>navigate(id as PageId)})),{id:'add-directory',title:'添加游戏目录',description:'自动识别目录中的实例',icon:'folderPlus',action:()=>run('source','source.add')},{id:'scan',title:'重新扫描实例',description:'刷新已登记的全部目录',icon:'refresh',action:()=>run('scan','scan')},{id:'new-tab',title:'新建实例标签',description:'在当前栏打开新标签',icon:'plus',action:()=>addTab()},...data.state.presets.map(p=>({id:p.id,title:'应用预设：'+p.name,description:'恢复此预设的布局与标签',icon:'preset',action:()=>{maximizedPane.value=null;workspace.value=repairWorkspace(plain(p.workspace))}})),...data.instances.map(i=>({id:i.id,title:i.name,description:i.minecraft+' · '+i.loader,icon:'instances',action:()=>{navigate('instances');tabOf(activePane.value).query=i.name}}))]
  all.push({id:'java-manager',title:'打开 Java 管理',description:'检测本机 Java 或手动指定运行环境',icon:'java',action:()=>navigate('tools')},{id:'accounts',title:'账户管理',description:'添加和切换 Microsoft 或离线账户',icon:'user',action:openAccounts})
  const q=commandQuery.value.trim().toLowerCase();return all.filter(c=>!q||`${c.title} ${c.description}`.toLowerCase().includes(q)).slice(0,20)
})
function executeCommand(command:typeof commands.value[number]){commandOpen.value=false;commandQuery.value='';void command.action()}
function commandKey(event:KeyboardEvent){if(event.key==='ArrowDown'){event.preventDefault();commandIndex.value=Math.min(commands.value.length-1,commandIndex.value+1)}else if(event.key==='ArrowUp'){event.preventDefault();commandIndex.value=Math.max(0,commandIndex.value-1)}else if(event.key==='Enter'&&commands.value[commandIndex.value]){event.preventDefault();executeCommand(commands.value[commandIndex.value])}}
function keydown(event:KeyboardEvent){
  const input=(event.target as HTMLElement)?.matches('input,textarea,select,[contenteditable]')
  const ctrl=event.ctrlKey||event.metaKey,key=event.key.toLowerCase()
  if(event.key==='Escape'){tabContext.value=null;commandOpen.value=false;presetOpen.value=false;savePresetOpen.value=false;if(!loginPending.value)accountOpen.value=false;return}
  if(ctrl&&key==='k'){event.preventDefault();commandOpen.value=!commandOpen.value;commandQuery.value=''}
  else if(ctrl&&event.shiftKey&&key==='t'){event.preventDefault();if(!restoreWorkspaceTab(workspace.value))toast('没有可恢复的标签，或目标栏已达到标签上限');else if(maximizedPane.value)maximizedPane.value=workspace.value.focused}
  else if(ctrl&&key==='t'){event.preventDefault();addTab()}
  else if(ctrl&&key==='w'){event.preventDefault();const tab=tabOf(activePane.value);if(!tab.pinned)closeTab(activePane.value,tab)}
  else if(ctrl&&key==='b'){event.preventDefault();toggleSidebar(workspace.value)}
  else if(ctrl&&key==='tab'){event.preventDefault();const p=activePane.value,index=p.tabs.findIndex(t=>t.id===p.active);p.active=p.tabs[(index+(event.shiftKey?-1:1)+p.tabs.length)%p.tabs.length].id}
  else if(ctrl&&/^[0-5]$/.test(key)){event.preventDefault();setLayout((['single','columns','rows','left-wide','right-wide','quad'] as LayoutId[])[Number(key)])}
  else if(event.key==='F5'){event.preventDefault();void run('scan','scan')}
  else if(event.key==='/'&&!input){event.preventDefault();workspaceElement.value?.querySelector<HTMLElement>(`[data-pane="${activePane.value.id}"] input[aria-label="搜索实例"]`)?.focus()}
}

onMounted(async()=>{
  measureNav()
  window.addEventListener('resize',measureNav)
  stopEvents=window.launcher?.onEvent(async event=>{
    if(event.type==='snapshot'){applySnapshot(event.data);maximized.value=!!(event.data as any)?.maximized}
    if(event.type==='tasks')data.tasks=event.data
    if(event.type==='log'){data.logs.push(event.data);if(data.logs.length>1500)data.logs.splice(0,data.logs.length-1500)}
    if(event.type==='notice')toast(event.data)
    if(event.type==='loginStage'){loginStage.value=event.data.stage}
    if(event.type==='deviceCode'){deviceCode.value=event.data;accountOpen.value=true}
    if(event.type==='loginFinished'){loginPending.value=false;deviceCode.value=null}
    if(event.type==='windowState')maximized.value=!!event.data?.maximized
    if(event.type==='closeRequested'){clearTimeout(saveTimer);try{await persist();await api('window.closeReady')}catch{toast('工作区未能保存，窗口已保留，请检查程序目录写入权限。')}}
  })
  await initialize();window.addEventListener('keydown',keydown)
  try{const notice=await api<string>('app.takeNotice');if(notice)toast(notice)}catch{}
  for(const a of data.state.accounts) if(a.kind==='microsoft'&&!(a as any).skin) void api('account.refresh',a.id).catch(()=>{})
})
onUnmounted(()=>{stopEvents?.();window.removeEventListener('keydown',keydown);window.removeEventListener('resize',measureNav);clearTimeout(saveTimer)})
</script>

<template>
  <div class="application" :class="{resizing}">
    <header class="titlebar"><div v-if="navStyle==='top'" class="account-switcher" @mouseenter="accountMenuOpen=true" @mouseleave="accountMenuOpen=false"><button class="titlebar-account" :title="account?account.name+' · 账户管理':'添加账户'" @click="openAccounts()"><AccountAvatar v-if="account" :account="account" :size="24"/><span v-else class="account-avatar"><Icon name="user" :size="14"/></span><span v-if="!navCompact" class="account-name">{{account?account.name:'账户'}}</span></button><div v-if="accountMenuOpen" class="account-strip"><button v-for="a in otherAccounts.slice(0,4)" :key="a.id" class="account-chip" :title="a.name" :data-name="a.name" @click="run(a.id,'account.select',a.id).then(()=>{accountMenuOpen=false})"><AccountAvatar :account="a" :size="22"/></button><button v-if="otherAccounts.length>4" class="account-chip more" :title="'还有 '+(otherAccounts.length-4)+' 个账户'" :data-name="'还有 '+(otherAccounts.length-4)+' 个账户'" @click="openAccounts()">+{{otherAccounts.length-4}}</button><button class="account-chip add" title="添加账户" data-name="添加账户" @click="openAccounts()"><Icon name="plus" :size="14"/></button></div></div><nav v-if="navStyle==='top'" class="top-nav" :class="{compact:navCompact}" aria-label="模块切换"><button v-for="page in allPages" :key="page" :class="{active:activePage===page}" :title="pages[page].title" @click="navigate(page)"><Icon :name="page" :size="17"/><span v-if="!navCompact">{{pages[page].title}}</span><span v-if="page==='tasks'&&activeTasks" class="nav-count task-count">{{activeTasks}}</span><span v-if="page==='plugins'" class="new-dot"/></button><span class="toolbar-divider"/><button class="top-nav-search" :class="{active:commandOpen}" title="搜索与命令" aria-label="搜索与命令" @click="commandOpen=true"><Icon name="search" :size="16"/><span v-if="!navCompact">搜索</span><kbd v-if="!navCompact">Ctrl K</kbd></button></nav><div class="titlebar-center titlebar-workspace"><div class="workspace-actions"><div v-if="navStyle==='top'||workspace.sidebarCollapsed" class="layout-picker"><span v-if="!navCompact" class="layout-label">布局</span><button v-for="layout in layoutIds" :key="layout" :class="{selected:workspace.layout===layout}" :title="layoutNames[layout]" :aria-label="layoutNames[layout]" @click="setLayout(layout)"><Icon :name="layout" :size="17"/></button></div><span class="toolbar-divider"/><div class="preset-menu-wrapper"><button class="toolbar-button" :class="{active:presetOpen}" title="工作区预设" @click="presetOpen=!presetOpen"><Icon name="preset" :size="15"/><span v-if="!presetCompact">工作区预设</span><Icon name="down" :size="12"/></button><div v-if="presetOpen" class="dropdown preset-dropdown"><div class="dropdown-label">已保存的工作区</div><p v-if="!data.state.presets.length" class="dropdown-empty">保存当前布局，随时切换。</p><div v-for="p in data.state.presets" :key="p.id" class="preset-item"><button @click="maximizedPane=null;workspace=repairWorkspace(plain(p.workspace));presetOpen=false"><Icon name="preset" :size="15"/>{{p.name}}</button><button class="bare" title="删除预设" @click="run(p.id,'preset.delete',p.id)"><Icon name="trash" :size="13"/></button></div><button class="dropdown-action" @click="presetOpen=false;savePresetOpen=true"><Icon name="plus" :size="15"/>保存当前工作区</button></div></div><span class="toolbar-divider"/><div class="nav-switch" role="group" aria-label="导航栏位置"><button class="top" :class="{active:navStyle==='top'}" title="导航在顶部" aria-label="导航在顶部" @click="navStyle='top'"><i/></button><button class="side" :class="{active:navStyle==='side'}" title="导航在左侧" aria-label="导航在左侧" @click="navStyle='side';workspace.sidebarCollapsed=false;workspace.sidebarWidth=Math.max(workspace.sidebarWidth,210)"><i/></button></div></div></div><div class="window-controls"><button title="最小化" aria-label="最小化" @click="run('minimize','window.minimize')"><Icon name="minus" :size="16"/></button><button :title="maximized?'还原':'最大化'" :aria-label="maximized?'还原':'最大化'" @click="run('maximize','window.maximize')"><Icon :name="maximized?'copy':'maximize'" :size="14"/></button><button class="window-close" title="关闭" aria-label="关闭启动器" @click="run('close','window.close')"><Icon name="x" :size="17"/></button></div></header>
    <div class="resize-handles" aria-hidden="true"><i data-edge="top"/><i data-edge="bottom"/><i data-edge="left"/><i data-edge="right"/><i data-edge="topleft"/><i data-edge="topright"/><i data-edge="bottomleft"/><i data-edge="bottomright"/></div>
    <div class="app-body"><aside v-if="navStyle==='side'" class="sidebar" :class="{collapsed:workspace.sidebarCollapsed,'sidebar-dragging':sidebarDragging}" :style="sidebarStyle"><div class="sidebar-top"><div class="sidebar-label">工作空间</div><nav><button v-for="page in navigation" :key="page" :class="{active:activePage===page}" @click="navigationClick($event,page)" @auxclick.middle.prevent="addTab(activePane,page,false)" :title="pages[page].title"><Icon :name="page" :size="19"/><span>{{pages[page].title}}</span><span v-if="page==='instances'&&data.instances.length" class="nav-count">{{data.instances.length}}</span><span v-if="page==='tasks'&&activeTasks" class="nav-count task-count">{{activeTasks}}</span></button></nav><button class="search-shortcut" @click="commandOpen=true"><Icon name="search" :size="16"/><span>搜索与命令</span><kbd>Ctrl K</kbd></button><div class="sidebar-divider"/><div class="sidebar-label">启动器</div><nav><button v-for="page in utilities" :key="page" :class="{active:activePage===page}" @click="navigationClick($event,page)" @auxclick.middle.prevent="addTab(activePane,page,false)" :title="pages[page].title"><Icon :name="page" :size="19"/><span>{{pages[page].title}}</span><span v-if="page==='plugins'" class="new-dot"/></button></nav><template v-if="!workspace.sidebarCollapsed"><div class="sidebar-divider"/><div class="sidebar-layout"><div class="sidebar-label">布局</div><div class="layout-picker"><button v-for="layout in layoutIds" :key="layout" :class="{selected:workspace.layout===layout}" :title="layoutNames[layout]" :aria-label="layoutNames[layout]" @click="setLayout(layout)"><Icon :name="layout" :size="17"/></button></div></div></template></div><div class="sidebar-bottom"><div class="account-strip" @mouseenter="sideAccountHover=true" @mouseleave="sideAccountHover=false"><button class="account-current" @click="openAccounts"><AccountAvatar v-if="account" :account="account" :size="26"/><span v-else class="avatar"><Icon name="user" :size="19"/></span><span><b>{{account?.name||'添加账户'}}</b><small>{{account?(account.kind==='offline'?'离线账户':'Microsoft 账户'):'选择账户后启动'}}</small></span></button><button class="bare account-add" title="添加或管理账户" aria-label="添加账户" @click="openAccounts"><Icon name="plus" :size="19"/></button><div v-if="sideAccountHover&&otherAccounts.length" class="side-account-list"><button v-for="a in otherAccounts" :key="a.id" @click="run(a.id,'account.select',a.id)"><AccountAvatar :account="a" :size="22"/><span>{{a.name}}</span></button></div></div><div v-if="data.state.accounts.length>1" class="account-avatars"><button v-for="a in data.state.accounts" :key="a.id" :title="a.name" :class="{selected:a.id===data.state.selectedAccount}" @click="run(a.id,'account.select',a.id)"><AccountAvatar :account="a" :size="20"/></button></div></div><div class="sidebar-resizer" role="separator" aria-label="调整侧栏宽度" aria-orientation="vertical" tabindex="0" @pointerdown="sidebarResize" @dblclick="workspace.sidebarWidth=210;workspace.sidebarExpandedWidth=210;workspace.sidebarCollapsed=false" @keydown.left.prevent="resizeSidebar(workspace,workspace.sidebarWidth-8)" @keydown.right.prevent="resizeSidebar(workspace,workspace.sidebarWidth+8)"/></aside>
    <main class="main-area">
      <div v-if="!connected" class="preview-notice"><Icon name="warning" :size="15"/>桌面服务未连接。请运行桌面程序以管理目录和启动游戏。</div>
      <div ref="workspaceElement" class="workspace" :class="displayLayout" :style="workspaceStyle"><section v-for="(pane,index) in displayPanes" :key="pane.id" :data-pane="pane.id" class="pane" :class="{focused:workspace.focused===pane.id,'drop-target':dragging&&dragging!==pane.id}" :style="{gridArea:['a','b','c','d'][index]}" @pointerdown="focus(pane)" @dragover.prevent @drop.prevent="drop($event,pane)"><div class="tab-bar"><div class="tabs"><div v-for="tab in pane.tabs" :key="tab.id" class="tab" :class="{active:pane.active===tab.id,pinned:tab.pinned}" draggable="true" @dragstart="startDrag($event,pane,tab)" @dragend="dragging=''" @dragover.prevent.stop @drop.prevent.stop="drop($event,pane,tab)" @click="pane.active=tab.id;focus(pane)" @auxclick.middle.prevent="closeTab(pane,tab)" @contextmenu.prevent.stop="showTabMenu($event,pane,tab)"><Icon :name="tab.page" :size="14"/><span>{{pages[tab.page].title}}</span><button v-if="tab.pinned" class="tab-pin" title="取消固定" @click.stop="tab.pinned=false"><Icon name="pin" :size="11"/></button><button class="tab-close" :aria-label="'关闭'+pages[tab.page].title+'标签'" @click.stop="closeTab(pane,tab)"><Icon name="x" :size="12"/></button><div v-if="pane.active===tab.id" class="tab-active-actions"><button title="新建实例标签" aria-label="新建标签" @click.stop="addTab(pane)"><Icon name="plus" :size="13"/></button><button title="复制当前标签" aria-label="复制标签" @click.stop="duplicateTab(pane,tab)"><Icon name="copy" :size="12"/></button><button v-if="!tab.pinned" class="pin-action" title="固定当前标签" @click.stop="tab.pinned=true"><Icon name="pin" :size="12"/></button></div></div></div><button class="pane-number" :title="maximizedPane?'恢复分栏':'临时最大化当前栏'" :aria-label="maximizedPane?'恢复分栏':'临时最大化栏'+(workspace.panes.indexOf(pane)+1)" @click="focusPane(pane)"><Icon :name="maximizedPane?'columns':'maximize'" :size="12"/><span>0{{workspace.panes.indexOf(pane)+1}}</span></button></div><PaneView :key="pane.id" :tab="tabOf(pane)" :pane-id="pane.id" @navigate="navigate($event,pane)" @login="openAccounts"/></section>
      <div v-if="!maximizedPane&&workspace.layout!=='rows'&&workspace.layout!=='single'" class="splitter vertical" :style="{left:workspace.ratios[0]+'%'}" role="separator" aria-label="调整左右分栏比例" aria-orientation="vertical" tabindex="0" @pointerdown="resize($event,0,'x')" @dblclick="workspace.ratios[0]=50" @keydown="adjustRatio($event,0)"/>
      <div v-if="!maximizedPane&&workspace.layout!=='columns'&&workspace.layout!=='single'" class="splitter horizontal" :class="{'right-half':workspace.layout==='left-wide','left-half':workspace.layout==='right-wide'}" :style="{top:workspace.ratios[workspace.layout.endsWith('wide')?2:1]+'%',left:workspace.layout==='left-wide'?workspace.ratios[0]+'%':'0',right:workspace.layout==='right-wide'?(100-workspace.ratios[0])+'%':'0'}" role="separator" aria-label="调整上下分栏比例" aria-orientation="horizontal" tabindex="0" @pointerdown="resize($event,workspace.layout.endsWith('wide')?2:1,'y')" @dblclick="workspace.ratios[workspace.layout.endsWith('wide')?2:1]=50" @keydown="adjustRatio($event,workspace.layout.endsWith('wide')?2:1)"/>
      </div>
      <footer class="statusbar"><div><span class="status-dot"/><span>{{activeTasks?activeTasks+' 个任务进行中':'就绪'}}</span><span class="statusbar-divider"/><Icon name="drive" :size="12"/><span>便携数据</span></div><div><span>工作区自动保存</span><span class="statusbar-divider"/><kbd>Ctrl K</kbd><span>命令面板</span><span class="statusbar-divider"/><span>HALF / {{data.appVersion}}</span></div></footer>
    </main></div>
    <template v-if="tabContext&&contextPane&&contextTab"><div class="context-dismiss" @pointerdown="tabContext=null" @contextmenu.prevent="tabContext=null"/><div class="tab-context-menu" role="menu" :style="{left:tabContext.x+'px',top:tabContext.y+'px'}"><div class="dropdown-label">{{pages[contextTab.page].title}}</div><button role="menuitem" @click="duplicateTab(contextPane,contextTab);tabContext=null"><Icon name="copy" :size="14"/>复制标签</button><button role="menuitem" @click="contextTab.pinned=!contextTab.pinned;tabContext=null"><Icon name="pin" :size="14"/>{{contextTab.pinned?'取消固定':'固定标签'}}</button><button role="menuitem" @click="focusPane(contextPane);tabContext=null"><Icon name="maximize" :size="14"/>{{maximizedPane?'恢复分栏':'临时最大化当前栏'}}</button><div class="dropdown-label">移动到分栏</div><button v-for="target in visiblePanes.filter(p=>p.id!==contextPane?.id)" :key="target.id" role="menuitem" @click="contextMove(target.id)"><Icon name="columns" :size="14"/>分栏 {{workspace.panes.indexOf(target)+1}}</button><button role="menuitem" @click="closeRelated('others')">关闭其他未固定标签</button><button role="menuitem" @click="closeRelated('right')">关闭右侧未固定标签</button><button role="menuitem" @click="closeTab(contextPane,contextTab);tabContext=null"><Icon name="x" :size="14"/>关闭当前标签</button></div></template>
    <Transition name="toast"><div v-if="notice" class="toast-notification" role="status"><Icon name="help" :size="18"/><span>{{notice}}</span><button class="bare" aria-label="关闭提示" @click="notice=''"><Icon name="x" :size="15"/></button></div></Transition>

    <div v-if="savePresetOpen" class="modal-backdrop" @click.self="savePresetOpen=false"><form class="modal small-modal" @submit.prevent="savePreset"><header><h2>保存工作区预设</h2><button type="button" class="bare" aria-label="关闭保存预设" @click="savePresetOpen=false"><Icon name="x"/></button></header><div class="modal-body"><label class="field-label">预设名称</label><input v-model="presetName" class="full-input" placeholder="例如：模组开发、生存日常" autofocus maxlength="80"/><p class="field-hint">保存当前布局、分栏比例、标签与页面筛选。</p></div><footer><button type="button" class="button" @click="savePresetOpen=false">取消</button><button class="button primary" :disabled="!presetName.trim()||busy.has('preset-save')">保存预设</button></footer></form></div>
    <div v-if="commandOpen" class="modal-backdrop command-backdrop" @click.self="commandOpen=false"><div class="command-modal"><div class="command-search"><Icon name="search" :size="21"/><input v-model="commandQuery" placeholder="搜索实例、页面、预设或操作…" autofocus aria-label="全局搜索和命令" @keydown="commandKey"/><kbd @click="commandOpen=false">ESC</kbd></div><div class="dropdown-label">{{commandQuery?'搜索结果':'快捷操作'}}</div><div class="command-results"><button v-for="(c,index) in commands" :key="c.id" :class="{'keyboard-active':commandIndex===index}" @click="executeCommand(c)"><span><Icon :name="c.icon" :size="18"/></span><div><b>{{c.title}}</b><small>{{c.description}}</small></div><Icon name="arrow" :size="15"/></button><div v-if="!commands.length" class="empty-state">没有找到匹配的操作</div></div><footer><span>输入关键词搜索</span><span><kbd>↵</kbd> 执行选中项</span></footer></div></div>
    <div v-if="accountOpen" class="modal-backdrop" @click.self="!loginPending&&(accountOpen=false)"><section class="modal account-modal"><header><div><h2>账户管理</h2></div><button class="bare" aria-label="关闭账户管理" @click="accountOpen=false"><Icon name="x"/></button></header><div class="modal-body"><div v-for="a in data.state.accounts" :key="a.id" class="account-card"><AccountAvatar :account="a" :size="40"/><div><h3>{{a.name}}</h3><p>{{a.kind==='offline'?'离线账户':'Microsoft'}} · {{a.id===data.state.selectedAccount?'当前账户':'已添加'}}</p></div><button v-if="a.id!==data.state.selectedAccount" class="button compact" @click="run(a.id,'account.select',a.id)">使用</button><Icon v-else name="success" class="green" :size="20"/><button class="bare" title="移除此账户" @click="run(a.id+'remove','account.remove',a.id)"><Icon name="logout" :size="17"/></button></div><div v-if="!data.state.accounts.length&&!deviceCode" class="account-intro"><span class="avatar large"><Icon name="user" :size="30"/></span><h3>让你的身份连接每个世界</h3><p>通过 Microsoft 官方验证页面登录，<br>启动器不会收集你的账户密码。</p></div><div class="segmented account-type-picker"><button :class="{active:accountAddType==='microsoft'}" :disabled="loginPending" @click="accountAddType='microsoft'">微软账户</button><button :class="{active:accountAddType==='offline'}" :disabled="loginPending" @click="accountAddType='offline'">离线账户</button></div><form v-if="accountAddType==='offline'" class="offline-form" @submit.prevent="addOffline"><label class="field-label">添加离线账户</label><div class="input-with-button"><input v-model="offlineName" aria-label="离线账户名称" placeholder="3–16 位字母、数字、下划线" maxlength="16"/><button class="button" :disabled="busy.has('offline-add')||!offlineName.trim()">添加</button></div><p class="field-hint">可用于单人游戏及允许离线身份的服务器。名称决定本地身份，请勿随意更换。</p></form><template v-if="accountAddType==='microsoft'"><div class="account-login-methods"><label><input v-model="loginMethod" type="radio" value="browser" :disabled="loginPending"/>默认浏览器授权（推荐）</label><label><input v-model="loginMethod" type="radio" value="device" :disabled="loginPending"/>设备代码登录</label><label><input v-model="loginMethod" type="radio" value="inapp" :disabled="loginPending"/>在应用内登录</label></div><p class="field-hint">浏览器授权会直接调用系统默认浏览器打开 Microsoft 页面，完成后自动回到启动器；浏览器打不开时可选“在应用内登录”，不依赖本机回调。</p><div v-if="deviceCode" class="device-code"><p>在 Microsoft 官方页面输入此代码</p><strong>{{deviceCode.code}}</strong><p class="device-url">{{deviceCode.url}}</p><div class="button-row"><button class="button" @click="run('copy-code','account.copyCode').then(ok=>{if(ok)toast('代码已复制')})">复制代码</button><button class="button" @click="run('copy-device-link','account.copyLink').then(ok=>{if(ok)toast('验证页面链接已复制')})">复制链接</button><button class="button primary" @click="run('microsoft','account.reopen')">打开验证页面<Icon name="external" :size="15"/></button><p class="field-hint">浏览器打不开时，可在手机或其他设备访问上面的链接并输入代码。</p></div></div><button v-if="!loginPending" class="button primary full-button" @click="login"><Icon name="plus" :size="17"/>{{loginMethod==='device'?'获取设备代码':loginMethod==='inapp'?'在应用内打开登录页':'浏览器授权'}}</button><div v-else class="login-wait"><Icon name="loading" class="spin" :size="17"/><span>{{loginStage||'等待 Microsoft 授权…'}}</span><button class="text-link" @click="run('reopen-login','account.reopen')">重新打开网页</button><button class="text-link" @click="run('copy-link','account.copyLink').then(ok=>{if(ok)toast('登录链接已复制，可粘贴到浏览器打开')})">复制链接</button><button class="text-link" @click="cancelLogin">取消</button></div></template><div class="account-links"><button @click="run('website','open','website')">游戏官网<Icon name="external" :size="12"/></button><button @click="run('redeem','open','redeem')">兑换代码<Icon name="external" :size="12"/></button></div></div></section></div>
  </div>
</template>
